class Solution {
    public int subtractProductAndSum(int n) {
        int product = 1, sum = 0;
        while (n > 0) {
            int d = n % 10;
            product *= d;
            sum += d;
            n /= 10;
        }
        return product - sum;
    }
}

class Solution {
    public int subtractProductAndSum(int n) {
        String s = String.valueOf(n);
        int product = 1, sum = 0;
        for (int i = 0; i < s.length(); i++) {
            int d = s.charAt(i) - '0';
            product *= d;
            sum += d;
        }
        return product - sum;
    }
}
